"""
preprocess_imgbytes.py
- Selenium 캡처 바이트 이미지를 메모리에서 전처리하는 모듈
"""
from typing import Optional
import cv2
import numpy as np

from p_2607_forest.config import (
    IMG_WIDTH, IMG_HEIGHT,
    NUMBER_WIDTH_L, NUMBER_WIDTH_R,
    NUMBER_WIDTH, NUMBER_HEIGHT,
    IMG_LENGTH
)

def preprocess_captcha_from_imgbyte(img_bytes: bytes) -> Optional[np.ndarray]:
    """
    Selenium이 캡처한 캡챠이미지(6숫자) 바이트 데이터를 메모리 상에서
    바로 전처리하여 글자별 1차원 벡터의 배열로 반환합니다.

    :param img_bytes: driver.find_element(...).screenshot_as_png 결과값 (바이트)
    :return: (IMG_LENGTH, 1D_VECTOR_SIZE) 형태의 np.ndarray (float32)
    """
    if not img_bytes:
        return None

    # 1. 메모리 버퍼에서 그레이스케일로 디코딩
    nparr = np.frombuffer(img_bytes, np.uint8)
    img = cv2.imdecode(nparr, cv2.IMREAD_GRAYSCALE)

    if img is None:
        return None

    # 2. 고정 크기 리사이징 및 ROI 크롭
    img = cv2.resize(img, (IMG_WIDTH, IMG_HEIGHT))
    img = img[:NUMBER_HEIGHT, NUMBER_WIDTH_L:NUMBER_WIDTH_R]

    # 3. 픽셀 정규화 [0.0 ~ 1.0]
    img = img.astype(np.float32) / 255.0

    # 4. 글자 균등 분할 및 1차원 플랫(flatten)
    char_width = NUMBER_WIDTH // IMG_LENGTH
    char_images = []

    for i in range(IMG_LENGTH):
        start_x = i * char_width
        end_x = start_x + char_width
        char_img = img[:, start_x:end_x]
        char_images.append(char_img.flatten())

    return np.array(char_images, dtype=np.float32)

